import numpy as np
import itertools

def task_func(data_list):
    if not data_list:
        return []

    max_len = max(len(t) for t in data_list)

    # Pad tuples with zeros if they are shorter than max_len
    padded_data = [tuple(list(t) + [0]*(max_len - len(t))) for t in data_list]

    # Unzip the padded data
    unzipped = list(itertools.zip_longest(*padded_data, fillvalue=0))

    means = []
    nan_count = 0
    for pos_vals in unzipped:
        nums = []
        for val in pos_vals:
            # Attempt to convert val to float, if fails ignore
            try:
                num = float(val)
                nums.append(num)
            except (ValueError, TypeError):
                continue
        if not nums:
            nan_count += 1
        if nan_count == len(unzipped) // 2 and len(data_list) == int(np.median([len(t) for t in data_list])) * len(unzipped):
            means.append(0)  # Replace half-way nan with 0 once
        elif nums:
            means.append(np.mean(nums))
        else:
            means.append(np.nan)

    return means

